using System;
using Kamilunavo.RepairEmpire.Core;
using Kamilunavo.RepairEmpire.Gameplay;
namespace Kamilunavo.RepairEmpire.Validation {
public static class RepairRuleChecks {
 static int count; static void Check(bool v,string name){count++;if(!v)throw new Exception("REPAIR_RULE_FAIL "+name);}
 public static int Run(){count=0;var p=new RepairProfile();var day=new DateTime(2026,10,8,12,0,0,DateTimeKind.Utc);
 Check(!RepairRules.IsArrival(9,0,0),"lateral distance rejects false arrival");Check(!RepairRules.IsArrival(0,9,0),"longitudinal distance rejects arrival");Check(!RepairRules.IsArrival(0,0,3),"moving van cannot repair");Check(RepairRules.IsArrival(3,3,.5f),"stopped nearby van arrives");Check(!RepairRules.IsArrival(float.NaN,0,0),"invalid position rejected");
 Check(JobCatalog.All.Length==24,"24 usable calls");var ids=new System.Collections.Generic.HashSet<string>();var categories=new int[4];foreach(var j in JobCatalog.All){Check(ids.Add(j.Id),"unique call");Check(j.Reward>=120&&j.Reward<=420&&j.Xp>=90&&j.Xp<=220,"balanced job rewards");categories[j.CategoryIndex]++;}foreach(int n in categories)Check(n==6,"six calls each category");
 Check(RepairRules.XpTarget(p)==143,"concept XP level target");Check(RepairRules.BeginJob(p,"switch")==0,"unowned voltage tool blocks job");long t=RepairRules.BeginJob(p,"faucet");Check(t>0&&p.ActiveJob=="faucet","valid ticket begins job");Check(!RepairRules.AdvanceRepair(p,t+1,0),"wrong ticket rejected");Check(!RepairRules.AdvanceRepair(p,t,1),"out of order phase rejected");Check(!RepairRules.Complete(p,t,day,x=>true),"premature reward rejected");for(int i=0;i<3;i++){Check(RepairRules.AdvanceRepair(p,t,i),"ordered phase progresses");Check(!RepairRules.AdvanceRepair(p,t,i),"phase cannot repeat");}
 Check(!RepairRules.Complete(p,t,day,x=>false)&&p.Cash==1130&&p.RepairPhase==3,"failed persistence rolls back reward and repair");Check(!RepairRules.Complete(p,t,day,x=>{throw new Exception("disk");})&&p.CompletedJobs==0,"save exception rolls back");Check(RepairRules.Complete(p,t,day,x=>x.Cash==1250&&x.CompletedTicket==t),"persist before acknowledgment");Check(p.Cash==1250&&p.Level==3&&p.Xp==81&&p.CompletedJobs==1,"job pays correct XP cash");Check(RepairRules.BeginJob(p,"faucet")==0,"paid contract cannot be accepted again");Check(!RepairRules.Complete(p,t,day,x=>true)&&p.Cash==1250,"completion replay cannot mint");
 Check(RepairRules.BeginJob(p.Clone(),"faucet")==0,"paid guard survives profile clone");Check(!RepairRules.BuyTool(p,2)&&p.Cash==1250,"level gate pro kit");Check(RepairRules.BuyTool(p,1)&&p.Cash==850,"voltage tool purchase");Check(!RepairRules.BuyTool(p,1)&&p.Cash==850,"duplicate tool rejected");Check(RepairRules.BeginJob(p,"switch")>t,"new nonce monotonic");Check(!RepairRules.BuyVehicle(p,1),"insufficient funds cargo");p.Cash=5000;Check(RepairRules.BuyVehicle(p,1)&&p.Cash==4100,"cargo purchase");Check(!RepairRules.BuyVehicle(p,1),"duplicate vehicle rejected");Check(!RepairRules.BuyVehicle(p,2),"electric level gate");p.Level=5;Check(RepairRules.BuyVehicle(p,2)&&p.Cash==1700,"electric purchase");Check(!RepairRules.EquipVehicle(p,7)&&RepairRules.EquipVehicle(p,2)&&p.Vehicle==2,"owned vehicle equip");
 p.Cash=20000;for(int i=0;i<4;i++)Check(RepairRules.UpgradeWorkshop(p),"bounded workshop upgrade");Check(!RepairRules.UpgradeWorkshop(p)&&p.Workshop==5,"workshop cap");for(int i=0;i<3;i++)Check(RepairRules.Hire(p,day),"employee hired");Check(!RepairRules.Hire(p,day),"employee cap");int cash=p.Cash;Check(RepairRules.AccrueOffline(p,day.AddHours(2))==180&&p.Cash==cash+180,"two hour passive income");Check(RepairRules.AccrueOffline(p,day.AddHours(1))==0,"reversed UTC no income");Check(RepairRules.AccrueOffline(p,day.AddHours(24))==720,"eight hour offline cap");Check(RepairRules.AccrueOffline(p,day.AddHours(24))==0,"same time replay no income");
 var nested=new RepairProfile();long nt=RepairRules.BeginJob(nested,"faucet");for(int phase=0;phase<3;phase++)RepairRules.AdvanceRepair(nested,nt,phase);bool nestedPaid=true;Check(RepairRules.Complete(nested,nt,day,x=>{nestedPaid=RepairRules.Complete(nested,nt,day,y=>true);return true;})&&!nestedPaid&&nested.Cash==1250,"reentrant completion cannot mint reward");Check(!RepairRules.CanDispatch(0,0)&&RepairRules.CanDispatch(20,0),"dispatch requires departure from customer");var daily=new RepairProfile();Check(RepairRules.ClaimDaily(daily,day)==100,"first login");Check(RepairRules.ClaimDaily(daily,day)==0&&RepairRules.ClaimDaily(daily,day.AddDays(-1))==0,"daily replay and reversal");for(int i=1;i<=7;i++)Check(RepairRules.ClaimDaily(daily,day.AddDays(i))==Math.Min(160,100+i*10),"UTC consecutive streak");Check(RepairRules.ClaimDaily(daily,day.AddDays(9))==100,"skipped day resets streak");Check(RepairRules.ClaimDailyJobs(daily,day.AddDays(9))==0,"no unearned daily company bonus");
 var jobs=new RepairProfile{Level=2};for(int i=0;i<3;i++){long ticket=RepairRules.BeginJob(jobs,new[]{"faucet","toilet","sink"}[i]);for(int phase=0;phase<3;phase++)RepairRules.AdvanceRepair(jobs,ticket,phase);Check(RepairRules.Complete(jobs,ticket,day,x=>true),"three daily real calls");}Check(RepairRules.ClaimDailyJobs(jobs,day)==250,"three job bonus");Check(RepairRules.ClaimDailyJobs(jobs,day)==0&&RepairRules.ClaimDailyJobs(jobs,day.AddDays(-1))==0,"daily jobs replay reversal");Check(RepairRules.ClaimDailyJobs(jobs,day.AddDays(1))==0,"daily jobs expiry");
 var unknown=new RepairProfile{Schema=99,Cash=888,Level=1000};unknown.Normalize();Check(unknown.Cash==888&&unknown.Level==1000,"unknown schema untouched");Check(RepairRules.BeginJob(unknown,"faucet")==0&&!RepairRules.BuyTool(unknown,1)&&RepairRules.ClaimDaily(unknown,day)==0,"unknown schema transactions blocked");
 var futureView=new RepairProfile{Schema=99,Cash=999,Styles=new bool[0],Commerce=null,Rewards=null};var display=futureView.Presentation();Check(!display.Supported&&display.Styles.Length==8&&display.Commerce!=null&&display.Rewards!=null,"future schema has safe read only display");Check(futureView.Styles.Length==0&&futureView.Commerce==null&&futureView.Cash==999,"presentation leaves future source untouched");Check(!RepairRules.BuyStyle(display,1)&&!Monetization.CommerceRules.FulfillPending(display,Monetization.CommerceRules.Starter,"future-ui",x=>{}),"safe display cannot transact");
 var corrupt=new RepairProfile{Cash=-10,Level=-4,Xp=-8,Styles=null,Vehicle=99,VehicleMask=0,ToolMask=0,SavedX=float.NaN,SavedZ=float.PositiveInfinity};corrupt.Normalize();Check(corrupt.Cash==0&&corrupt.Level==1&&corrupt.Vehicle==0&&corrupt.ToolMask==1&&corrupt.VehicleMask==1,"normalization bounded defaults");Check(corrupt.Styles.Length==8&&corrupt.Styles[0]&&corrupt.SavedX==0&&corrupt.SavedZ==0,"safe defaults spatial and style");
 var hire=new RepairProfile{Level=4,Cash=5000,OfflineUtc=(long)(day.AddHours(-4)-new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc)).TotalSeconds};Check(RepairRules.Hire(hire,day),"hire after old no-employee period");Check(RepairRules.AccrueOffline(hire,day)==0,"new employee cannot earn before hire");
 var paint=new RepairProfile();Check(RepairRules.BuyStyle(paint,1)&&paint.Cash==1055,"earned paint cost");Check(!RepairRules.BuyStyle(paint,1)&&RepairRules.EquipStyle(paint,1),"duplicate paint and equip");Check(!RepairRules.EquipStyle(paint,7),"locked premium paint rejected");
 var exhausted=new RepairProfile{CompletedTicket=long.MaxValue,ActiveTicket=long.MaxValue};exhausted.Normalize();Check(RepairRules.BeginJob(exhausted,"faucet")==0,"ticket overflow cannot reopen paid nonce");
 string path=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"repair-save-check-"+Guid.NewGuid()+".txt");var storage=new RepairSave(path,x=>x.Schema+":"+x.Cash,text=>{var f=text.Split(':');return new RepairProfile{Schema=int.Parse(f[0]),Cash=int.Parse(f[1])};});
 try{var original=new RepairProfile{Cash=4321};Check(storage.Save(original),"real file persisted");Check(storage.Load().Cash==4321,"new read reloads persisted cash");original.Cash=5432;Check(storage.Save(original)&&storage.Load().Cash==5432,"atomic file replacement updates");System.IO.File.WriteAllText(path,"99:777");Check(storage.Load().Schema==99&&!storage.Save(new RepairProfile()),"future schema protects file");Check(System.IO.File.ReadAllText(path)=="99:777","future bytes never overwritten");System.IO.File.WriteAllText(path,"broken");var corruptStorage=new RepairSave(path,x=>"1:0",text=>{throw new FormatException();});Check(corruptStorage.Load().Schema==-1&&!corruptStorage.Save(new RepairProfile()),"corrupt file preserved and transactions blocked");Check(System.IO.File.ReadAllText(path)=="broken","corrupt bytes remain");}finally{foreach(string suffix in new[]{"",".tmp",".bak"})if(System.IO.File.Exists(path+suffix))System.IO.File.Delete(path+suffix);}
 var paidPath=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"repair-paid-check-"+Guid.NewGuid()+".txt");var paidStorage=new RepairSave(paidPath,x=>x.Cash+"|"+string.Join(",",x.CompletedContracts),text=>{var f=text.Split('|');return new RepairProfile{Cash=int.Parse(f[0]),CompletedContracts=f[1].Length==0?new string[0]:f[1].Split(',')};});try{var company=new RepairProfile();long contract=RepairRules.BeginJob(company,"faucet");for(int phase=0;phase<3;phase++)RepairRules.AdvanceRepair(company,contract,phase);Check(RepairRules.Complete(company,contract,day,paidStorage.Save),"paid identity persisted before reward acknowledgment");var diskCompany=paidStorage.Load();Check(diskCompany.Cash==1250&&RepairRules.BeginJob(diskCompany,"faucet")==0,"actual file reload rejects paid contract");}finally{foreach(string suffix in new[]{"",".tmp",".bak"})if(System.IO.File.Exists(paidPath+suffix))System.IO.File.Delete(paidPath+suffix);}var legacy=new RepairProfile{CompletedJobs=9,CompletedContracts=null};legacy.Normalize();Check(legacy.CompletedContracts.Length==0&&legacy.CompletedJobs==9,"legacy company keeps progress with safe identity defaults");
 var tutorial=new RepairTutorial();tutorial.Start(new RepairProfile(),284);Check(tutorial.Active&&tutorial.Step==0,"fresh guide starts steering");tutorial.Observe(new RepairProfile(),284,true,false,false,false,false);Check(tutorial.Step==1,"actual steering advances guide");tutorial.Observe(new RepairProfile(),280,false,true,false,false,false);Check(tutorial.Step==2,"actual throttle advances guide");tutorial.Observe(new RepairProfile(),260,false,false,false,false,false);Check(tutorial.Step==3,"travel toward pin advances guide");tutorial.Observe(new RepairProfile(),2,false,false,true,false,false);Check(tutorial.Step==4,"stopped arrival advances guide");tutorial.Observe(new RepairProfile(),2,false,false,true,true,false);Check(tutorial.Step==5,"opened actual repair advances guide");tutorial.Observe(new RepairProfile{CompletedJobs=1},0,false,false,false,false,false);Check(tutorial.Step==6,"real payout advances guide to tools");tutorial.Observe(new RepairProfile{CompletedJobs=1,ToolMask=3},0,false,false,false,false,false);Check(!tutorial.Active&&tutorial.Step==7,"owned voltage tool finishes guide");
 var pausedGuide=new RepairTutorial();pausedGuide.Start(new RepairProfile(),284);pausedGuide.Observe(new RepairProfile(),200,true,true,true,true,true);Check(pausedGuide.Step==0,"interrupted application grants no tutorial progress");pausedGuide.Stop();Check(!pausedGuide.Active,"guide can be skipped without touching economy");Console.WriteLine("REPAIR_RULE_PASS "+count);return count;
 }
#if REPAIR_RULE_EXE
 public static void Main(){Run();}
#endif
}}
